 "content": "def transform(grid):
    """Recolor full-width/full-height separator bands to color 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bands = set()
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row) and row[0] != 8:
            bands.update((r, c) for c in range(w))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if all(v == vals[0] for v in vals) and vals[0] != 8:
            bands.update((r, c) for r in range(h))
    for r, c in bands:
        out[r][c] = 2
    return out
